import React, { useEffect, useState } from 'react';
import api from '../api/axios';
import MovieCard from '../components/MovieCard';
import styles from './Home.module.css';

const genres = ['Action', 'Comedy', 'Drama', 'Horror', 'Romance', 'Thriller', 'Sci-Fi'];

export default function Home() {
  const [movies, setMovies] = useState([]);
  const [search, setSearch] = useState('');
  const [genre, setGenre] = useState('');
  const [loading, setLoading] = useState(true);
  const [inputVal, setInputVal] = useState('');

  useEffect(() => { fetchMovies(); }, [search, genre]);

  const fetchMovies = async () => {
    setLoading(true);
    try {
      const params = {};
      if (search) params.search = search;
      if (genre) params.genre = genre;
      const { data } = await api.get('/movies', { params });
      setMovies(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className={styles.hero}>
        <h1 className={styles.heroTitle}>Book Your Perfect Movie Night</h1>
        <p className={styles.heroSub}>Thousands of shows. One destination.</p>
        <div className={styles.heroSearch}>
          <input
            placeholder="Search movies, genres, languages..."
            value={inputVal}
            onChange={(e) => setInputVal(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && setSearch(inputVal)}
          />
          <button onClick={() => setSearch(inputVal)}>Search</button>
        </div>
      </div>

      <div className={styles.container}>
        <div className={styles.banner}>
          <div>
            <h3>🎉 Weekend Special Offers</h3>
            <p>Get 20% off on all VIP seats this weekend</p>
          </div>
          <button className={styles.bannerBtn}>Grab Deal</button>
        </div>

        <div className={styles.sectionHeader}>
          <h2 className={styles.sectionTitle}>Now Showing</h2>
        </div>

        <div className={styles.filters}>
          <button className={`${styles.filterBtn} ${!genre ? styles.active : ''}`} onClick={() => setGenre('')}>All</button>
          {genres.map((g) => (
            <button key={g} className={`${styles.filterBtn} ${genre === g ? styles.active : ''}`} onClick={() => setGenre(g)}>{g}</button>
          ))}
        </div>

        {loading ? (
          <p className={styles.loading}>⏳ Loading movies...</p>
        ) : movies.length === 0 ? (
          <p className={styles.empty}>No movies found.</p>
        ) : (
          <div className={styles.grid}>
            {movies.map((movie) => <MovieCard key={movie._id} movie={movie} />)}
          </div>
        )}
      </div>
    </>
  );
}
